module async_fifo #(parameter WIDTH = 8, parameter DEPTH = 8)
  (input wclk, input wrst_n, input winc, input [WIDTH-1:0] wdata, output wfull,
   input rclk, input rrst_n, input rinc, output [WIDTH-1:0] rdata, output rempty);

    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W  = ADDR_W + 1;

    // ---------------------------------------------------------------
    // Memory
    // ---------------------------------------------------------------
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    // ---------------------------------------------------------------
    // Write domain: binary and Gray write pointers
    // ---------------------------------------------------------------
    reg [PTR_W-1:0] wbin, wbin_next, wgray_next;
    reg [PTR_W-1:0] wptr_gray_snap;   // sampled read Gray pointer (synced)

    wire [ADDR_W-1:0] waddr = wbin[ADDR_W-1:0];
    wire              wgo   = winc & ~wfull;

    always @(posedge wclk or negedge wrst_n) begin
        if (!wrst_n) begin
            wbin  <= {PTR_W{1'b0}};
            wgray <= {PTR_W{1'b0}};
        end else begin
            wbin  <= wbin_next;
            wgray <= wgray_next;
        end
    end

    assign wbin_next  = wbin + (wgo ? {{(PTR_W-1){1'b0}},1'b1} : {PTR_W{1'b0}});
    assign wgray_next = (wbin_next >> 1) ^ wbin_next;

    // ---------------------------------------------------------------
    // Read domain: binary and Gray read pointers
    // ---------------------------------------------------------------
    reg [PTR_W-1:0] rbin, rbin_next, rgray_next;
    reg [PTR_W-1:0] rptr_gray_snap;   // sampled write Gray pointer (synced)

    wire [ADDR_W-1:0] raddr = rbin[ADDR_W-1:0];
    wire              rgo   = rinc & ~rempty;

    always @(posedge rclk or negedge rrst_n) begin
        if (!rrst_n) begin
            rbin  <= {PTR_W{1'b0}};
            rgray <= {PTR_W{1'b0}};
        end else begin
            rbin  <= rbin_next;
            rgray <= rgray_next;
        end
    end

    assign rbin_next  = rbin + (rgo ? {{(PTR_W-1){1'b0}},1'b1} : {PTR_W{1'b0}});
    assign rgray_next = (rbin_next >> 1) ^ rbin_next;

    // ---------------------------------------------------------------
    // Two-flop synchronisers for the crossing Gray pointers
    // ---------------------------------------------------------------
    // write Gray pointer -> read domain
    reg [PTR_W-1:0] wgray_sync1, wgray_sync2;
    always @(posedge rclk or negedge rrst_n) begin
        if (!rrst_n) begin
            wgray_sync1 <= {PTR_W{1'b0}};
            wgray_sync2 <= {PTR_W{1'b0}};
        end else begin
            wgray_sync1 <= wgray;
            wgray_sync2 <= wgray_sync1;
        end
    end

    // read Gray pointer -> write domain
    reg [PTR_W-1:0] rgray_sync1, rgray_sync2;
    always @(posedge wclk or negedge wrst_n) begin
        if (!wrst_n) begin
            rgray_sync1 <= {PTR_W{1'b0}};
            rgray_sync2 <= {PTR_W{1'b0}};
        end else begin
            rgray_sync1 <= rgray;
            rgray_sync2 <= rgray_sync1;
        end
    end

    assign rptr_gray_snap = wgray_sync2;
    assign wptr_gray_snap = rgray_sync2;

    // ---------------------------------------------------------------
    // Status flags, generated in their own clock domains
    // ---------------------------------------------------------------
    // Empty: read Gray pointer equals the synced write Gray pointer
    assign rempty = (rgray_next == rptr_gray_snap);

    // Full: synced read Gray pointer equals write Gray pointer with the
    // two MSBs inverted and the remaining bits equal (Gray wrap check)
    assign wfull = (wgray_next == {~rptr_gray_snap[PTR_W-1:PTR_W-2],
                                    rptr_gray_snap[PTR_W-3:0]});

    // ---------------------------------------------------------------
    // Data path
    // ---------------------------------------------------------------
    always @(posedge wclk) begin
        if (wgo)
            mem[waddr] <= wdata;
    end

    assign rdata = mem[raddr];

endmodule
